def fix_namespace_prefix_w(content):
    """
    Convert textos cujo padrão é `w:st="` em `w-st="`
    """
    # Handle edge case where content is None
    if content is None:
        return None

    # Handle edge case where content is an empty string
    if content == "":
        return ""

    # Replace all occurrences of `w:st="` with `w-st="`
    return content.replace("w:st=", "w-st=")

