def render(pieces, style):
    """Render the given version pieces into the requested style."""
    if not isinstance(pieces, list):
        raise TypeError("pieces must be a list")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    if style not in ["semver", "pep440"]:
        raise ValueError("style must be either 'semver' or 'pep440'")

    if style == "semver":
        return ".".join(str(piece) for piece in pieces)
    elif style == "pep440":
        return ".".join(str(piece) for piece in pieces) + ".dev0"
    else:
        raise ValueError("Invalid style")

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    if "+" in pieces:
        return "."
    else:
        return "+"

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("No commands specified")
    if not isinstance(commands, (list, tuple)):
        commands = [commands]
    if not args:
        raise ValueError("No arguments specified")
    if not isinstance(args, (list, tuple)):
        args = [args]
    if cwd and not os.path.isdir(cwd):
        raise ValueError("Invalid current working directory: {}".format(cwd))
    if env and not isinstance(env, dict):
        raise ValueError("Invalid environment dictionary: {}".format(env))
    if verbose and not isinstance(verbose, bool):
        raise ValueError("Invalid verbose value: {}".format(verbose))
    if hide_stderr and not isinstance(hide_stderr, bool):
        raise ValueError("Invalid hide_stderr value: {}".format(hide_stderr))

    # Create a new process group for the command
    process = subprocess.Popen(commands, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    # Wait for the command to finish
    try:
        stdout, stderr = process.communicate(input=args)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Command '{}' returned non-zero exit status {}".format(commands[0], e.returncode))

    # Check the return code
    if process.returncode != 0:
        raise RuntimeError("Command '{}' returned non-zero exit status {}".format(commands[0], process.returncode))

    # Return the output
    return stdout.decode("utf-8")

