def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list):
        raise TypeError("alphabet must be a list")
    if not all(isinstance(x, str) for x in alphabet):
        raise TypeError("alphabet must contain only strings")
    if padding is not None and not isinstance(padding, int):
        raise TypeError("padding must be an integer")

    if number == 0:
        return alphabet[0]

    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number //= len(alphabet)

    if padding is not None:
        result = result.rjust(padding, alphabet[0])

    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    try:
        for flow in flow_params:
            if register_value in flow:
                flow[register_number] = flow.pop(register_value)
    except KeyError:
        raise ValueError(f"Invalid register number: {register_number}")
    except TypeError:
        raise TypeError("Invalid flow_params type, must be a dictionary")

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise ValueError("value must be a string")
    if not isinstance(arg, str):
        raise ValueError("arg must be a string")
    return value.replace(".", arg)

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError("Name must be a string")
    if name.startswith('"') and name.endswith('"'):
        return name[1:-1]
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    if platform == 'this':
        platform = sys.platform
    if platform == 'win32':
        return _split_windows(s)
    else:
        return _split_posix(s)

def _split_windows(s):
    # Use a regular expression to split the string into tokens,
    # treating double quotes as a special case.
    tokens = re.split(r'(\"[^\"]*\")', s)
    result = []
    for token in tokens:
        if token.startswith('"') and token.endswith('"'):
            # If the token is surrounded by double quotes, remove them.
            result.append(token[1:-1])
        else:
            # Otherwise, split the token by spaces.
            result.extend(token.split())
    return result

def _split_posix(s):
    # Use a regular expression to split the string into tokens,
    # treating single quotes as a special case.
    tokens = re.split(r"('[^']*')", s)
    result = []
    for token in tokens:
        if token.startswith("'") and token.endswith("'"):
            # If the token is surrounded by single quotes, remove them.
            result.append(token[1:-1])
        else:
            # Otherwise, split the token by spaces.
            result.extend(token.split())
    return result

def prepare_repository_from_archive(archive_path: str, filename: Optional[str] = None, tmp_path: Union[PosixPath, str] = "/tmp") -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Step 1: Check if the archive exists
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive file {archive_path} does not exist")

    # Step 2: Create a temporary directory to extract the archive
    tmp_dir = tempfile.mkdtemp(dir=tmp_path)

    # Step 3: Extract the archive
    try:
        subprocess.run(["tar", "-xvf", archive_path, "-C", tmp_dir], check=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Failed to extract archive {archive_path}") from e

    # Step 4: Find the extracted repository directory
    repo_dir = None
    for root, dirs, files in os.walk(tmp_dir):
        if filename and filename in files:
            repo_dir = root
            break

    # Step 5: Return the file repo url
    if repo_dir:
        return f"file://{repo_dir}"
    else:
        raise RuntimeError(f"Failed to find repository directory in extracted archive {archive_path}")

def parse_frequency(frequency):
    if frequency is None or frequency.lower() == "always":
        return None

    try:
        number, unit = frequency.split()
        number = int(number)
        if unit == "day" or unit == "days":
            return datetime.timedelta(days=number)
        elif unit == "week" or unit == "weeks":
            return datetime.timedelta(weeks=number)
        elif unit == "month" or unit == "months":
            return datetime.timedelta(days=number * 30)
        elif unit == "year" or unit == "years":
            return datetime.timedelta(days=number * 365)
        else:
            raise ValueError(f"Invalid unit of time: {unit}")
    except ValueError:
        raise ValueError(f"Invalid frequency: {frequency}")

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        if os.name == "nt" and "GIT_BASH" in os.environ:
            return True
        else:
            return False
    except Exception as e:
        print("Error in is_gitbash():", e)
        return False

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    if not isinstance(pattern, str):
        raise TypeError("Pattern must be a string")

    if strip:
        pattern = pattern.strip()

    try:
        return re.compile(pattern)
    except re.error:
        raise ValueError("Invalid regex pattern")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not isinstance(commands, list):
        commands = [commands]
    if not isinstance(args, list):
        args = [args]
    if cwd is None:
        cwd = os.getcwd()
    if env is None:
        env = os.environ.copy()
    if verbose:
        print("Running command:", " ".join(commands + args))
    try:
        result = subprocess.run(commands + args, cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if result.returncode != 0:
            raise RuntimeError("Command failed with exit code {}".format(result.returncode))
        if hide_stderr:
            return result.stdout.decode("utf-8").strip()
        else:
            return result.stdout.decode("utf-8").strip(), result.stderr.decode("utf-8").strip()
    except FileNotFoundError:
        raise RuntimeError("Command not found: {}".format(commands[0]))

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
    try:
        ipaddress.ip_address(target)
        return True
    except ValueError:
        return False

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    try:
        return yaml.dump(obj, dumper=dumper)
    except yaml.YAMLError as e:
        raise ValueError("Failed to dump object to YAML string") from e

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    return np.exp(-((x - 0.2) ** 2) / (2 * (0.1 ** 2)))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configs = {}
    errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as f:
                config = yaml.safe_load(f)
                configs[config_filename] = config
        except FileNotFoundError:
            errors.append(logging.LogRecord(logging.ERROR, 'Configuration file not found: {}'.format(config_filename)))
        except yaml.YAMLError as e:
            errors.append(logging.LogRecord(logging.ERROR, 'Error parsing configuration file: {}'.format(config_filename)))

    if overrides:
        for key, value in overrides.items():
            for config_filename, config in configs.items():
                if key in config:
                    config[key] = value

    if resolve_env:
        for config_filename, config in configs.items():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('$'):
                    env_var = value[1:]
                    if env_var in os.environ:
                        config[key] = os.environ[env_var]

    return configs, errors

def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        return {version: cls._get_handler_class(version) for version in cls._supported_versions}
    else:
        if not isinstance(protocol_version, tuple):
            raise TypeError("Protocol version must be passed as a tuple")
        if protocol_version not in cls._supported_versions:
            raise ValueError(f"Unsupported protocol version: {protocol_version}")
        return {protocol_version: cls._get_handler_class(protocol_version)}

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    bookmarks = []
    for value in values:
        try:
            bookmark = Bookmark.from_raw_value(value)
            bookmarks.append(bookmark)
        except ValueError:
            pass
    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if not isinstance(seq, collections.abc.Sequence):
        raise TypeError("seq must be a sequence type")
    if bufsize is not None and not isinstance(bufsize, int):
        raise TypeError("bufsize must be an integer")

    if isinstance(seq, str):
        return (seq, "str")
    elif isinstance(seq, bytes):
        return (seq, "bytes")
    elif isinstance(seq, bytearray):
        return (seq, "bytearray")
    elif isinstance(seq, memoryview):
        return (seq, "memoryview")
    elif isinstance(seq, array.array):
        return (seq, "array")
    elif isinstance(seq, collections.abc.Sequence):
        return (seq, "sequence")
    else:
        raise TypeError("seq must be a sequence type")

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a type")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a type")
    if not issubclass(candidate, iface):
        raise TypeError("candidate must be a subclass of iface")
    if tentative and not issubclass(candidate, tentative):
        raise TypeError("candidate must be a subclass of tentative")
    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc
    metaclasses = set()
    for base in bases:
        if hasattr(base, '__class__'):
            metaclasses.add(base.__class__)
    if len(metaclasses) == 1:
        return metaclasses.pop()
    else:
        raise TypeError("Inconsistent metaclasses found")

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
        del self[key]
        return value
    except KeyError:
        if default is not __marker:
            return default
        else:
            raise

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self:
        raise KeyError("popitem(): dictionary is empty")

    min_count = float("inf")
    min_key = None
    for key, (value, count) in self.items():
        if count < min_count:
            min_count = count
            min_key = key

    if min_key is None:
        raise KeyError("popitem(): dictionary is empty")

    value = self[min_key]
    del self[min_key]
    return (min_key, value)

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        regex = r"^in\s*=\s*(?P<in_value>.*)$"
        return re.compile(regex)
    except re.error as e:
        raise ValueError("Invalid in-style parameter regular expression") from e

def _create_converter(self) -> _converting._Converter:
    """
    Create the parameter style converter.

    Returns the parameter style converter (:class:`._converting._Converter`).
    """
    try:
        converter = _converting._Converter()
        return converter
    except Exception as e:
        raise e

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        if request.public_message:
            return True
        elif request.private_message:
            return True
        elif request.legacy_payload:
            return True
        else:
            return False
    except Exception as e:
        print(f"Error identifying request: {e}")
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    try:
        if request.headers["Content-Type"] == "application/json":
            data = json.loads(request.body)
            if data["type"] == "matrix":
                return True
        return False
    except (KeyError, ValueError):
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if not isinstance(dt, datetime):
        raise TypeError("dt must be a datetime object")
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        response = requests.head(url)
        return response.headers.get("Content-Type")
    except requests.exceptions.RequestException:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        raise TypeError("Tag must be a string")
    if len(tag) < 1 or len(tag) > 10:
        raise ValueError("Tag must be between 1 and 10 characters long")
    if not tag.isalnum():
        raise ValueError("Tag must contain only letters and digits")
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node.children:
        if child.tag not in result:
            result[child.tag] = []
        result[child.tag].append(child)
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("URL is required")
    if not document_path:
        document_path = "/.well-known/nodeinfo"
    try:
        response = requests.get(url + document_path)
        if response.status_code == 200:
            return response.json()
        else:
            raise ValueError("Invalid response from server")
    except requests.exceptions.RequestException as e:
        raise ValueError("Error connecting to server") from e
    except json.JSONDecodeError as e:
        raise ValueError("Invalid JSON response from server") from e

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        response = requests.get(f"https://{handle}/.well-known/webfinger")
        if response.status_code == 200:
            return response.json()
        else:
            return None
    except requests.exceptions.RequestException:
        return None

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    try:
        response = requests.get(f"https://{host}/.well-known/host-meta.json")
        response.raise_for_status()
        return XRD.from_json(response.json())
    except requests.exceptions.RequestException as e:
        raise DiasporaError(f"Failed to retrieve host-meta from {host}") from e

def ansible_config_manager(cls):
    """Gets the ansible config manager.

    Returns:
        AnsibleConfigManager: The ansible config manager.
    """
    try:
        from ansible.config.manager import ConfigManager
        return ConfigManager()
    except ImportError:
        raise ImportError("Ansible is not installed.") from None

def validate_from_content(cls, spec_content=None):
    """
    Validates that spec (YAML) content has all required fields.

    :param spec_content: Content of spec file
    :raise IRValidatorException: When mandatory data is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """
    try:
        spec_dict = yaml.safe_load(spec_content)
        required_fields = ['name', 'version', 'description', 'author', 'email']
        for field in required_fields:
            if field not in spec_dict:
                raise IRValidatorException(f'Missing required field: {field}')
        return spec_dict
    except yaml.YAMLError as e:
        raise IRValidatorException(f'Invalid YAML content: {e}')

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources.

    Args:
        self: The object instance.

    Returns:
        A dictionary containing the resolved argument values.

    Raises:
        ValueError: If the spec is invalid or cannot be resolved.
    """
    # Step 1: Validate the spec
    if not self.spec:
        raise ValueError("Spec is required")

    # Step 2: Resolve the argument values
    resolved_args = {}
    for arg_name, arg_value in self.spec.items():
        if arg_value is None:
            resolved_args[arg_name] = self.get_default_value(arg_name)
        else:
            resolved_args[arg_name] = arg_value

    return resolved_args

def get_deprecated_args(self):
    """Returning dict with options which deprecate others. """
    deprecated_args = {}
    for arg in self.args:
        if arg.deprecated:
            deprecated_args[arg.name] = arg.deprecated_by
    return deprecated_args

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # Check if the argument is deprecated
    for arg in cli_args:
        if arg in self.deprecated_args:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version.")

    # Check if the argument is deprecated in the answer file
    for arg in answer_file_args:
        if arg in self.deprecated_args:
            print(f"Warning: The argument '{arg}' is deprecated and will be removed in a future version.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    try:
        command = self.get_command(command_name)
        return command.option_specs
    except KeyError:
        raise ValueError(f"Invalid command name: {command_name}")
    except AttributeError:
        raise ValueError(f"Command {command_name} does not have any options")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg in args:
        if arg not in self.choices:
            raise ValueError(f"Invalid choice: {arg}. Must be one of {self.choices}")

    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Check if the number of arguments is valid
    if len(args) != 2:
        raise ValueError("Invalid number of arguments. Expected 2, received {}.".format(len(args)))

    # Check if the arguments are of the correct type
    if not isinstance(args[0], int) or not isinstance(args[1], int):
        raise TypeError("Invalid argument type. Expected int, received {} and {}.".format(type(args[0]), type(args[1])))

    # Check if the first argument is less than or equal to the second argument
    if args[0] > args[1]:
        raise ValueError("Invalid argument value. The first argument must be less than or equal to the second argument.")

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for arg in args:
        if arg.startswith("control_"):
            control_args[arg] = args[arg]
        elif arg.startswith("nested_"):
            nested_args[arg] = args[arg]
        else:
            custom_args[arg] = args[arg]

    return control_args, nested_args, custom_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    for key, value in extra_vars.items():
        if key not in vars_dict:
            vars_dict[key] = value
        elif isinstance(vars_dict[key], list):
            vars_dict[key].extend(value)
        else:
            vars_dict[key] = [vars_dict[key], value]
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down directly to Ansible.
    """
    # Step 1: Validate input parameters
    if not isinstance(ir_workspace, InfraredWorkspace):
        raise ValueError("ir_workspace must be an InfraredWorkspace object")
    if not isinstance(ir_plugin, InfraredPlugin):
        raise ValueError("ir_plugin must be an InfraredPlugin object")
    if not isinstance(playbook_path, str):
        raise ValueError("playbook_path must be a string")
    if verbose is not None and not isinstance(verbose, int):
        raise ValueError("verbose must be an integer")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise ValueError("extra_vars must be a dict")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise ValueError("ansible_args must be a dict")

    # Step 2: Set up the Ansible environment
    ansible_env = os.environ.copy()
    ansible_env["ANSIBLE_CONFIG"] = ir_workspace.get_ansible_config_path()
    ansible_env["ANSIBLE_ROLES_PATH"] = ir_workspace.get_ansible_roles_path()
    ansible_env["ANSIBLE_INVENTORY"] = ir_workspace.get_ansible_inventory_path()

    # Step 3: Build the Ansible command
    ansible_cmd = ["ansible-playbook", playbook_path]
    if verbose is not None:
        ansible_cmd.append("-" + str(verbose))
    if extra_vars is not None:
        for key, value in extra_vars.items():
            ansible_cmd.append("-e")
            ansible_cmd.append(f"{key}={value}")
    if ansible_args is not None:
        for key, value in ansible_args.items():
            ansible_cmd.append(f"--{key}")
            ansible_cmd.append(value)

    # Step 4: Run the Ansible command
    result = subprocess.run(ansible_cmd, env=ansible_env, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    # Step 5: Return the result
    return result.stdout.decode("utf-8")

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    try:
        with open(os.path.join(plugin_dir, "plugin.spec"), "r") as f:
            spec = yaml.safe_load(f)
    except FileNotFoundError:
        raise ValueError(f"Plugin spec file not found in {plugin_dir}")
    except yaml.YAMLError:
        raise ValueError(f"Invalid YAML format in plugin spec file {plugin_dir}/plugin.spec")

    flatten_dict = {}
    for key, value in spec.items():
        if isinstance(value, dict):
            for subkey, subvalue in value.items():
                flatten_dict[f"{key}.{subkey}"] = subvalue
        else:
            flatten_dict[key] = value

    return flatten_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if not os.environ.get("CONFIG_PATH"):
        os.environ["CONFIG_PATH"] = "/path/to/config.ini"
    return os.environ["CONFIG_PATH"]

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not path.startswith(root):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    return path[len(root):]
